package com.fincore.fincore.transaction; import java.math.BigDecimal; import java.time.Instant; import com.fincore.fincore.account.Account; import com.fincore.fincore.user.User; import jakarta.persistence.*; @Entity @Table(name="transactions") public class FinanceTransaction { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,precision=19,scale=2) private BigDecimal amount; @Column(nullable=false,length=80) private String category; @Column(length=255) private String description; @Enumerated(EnumType.STRING) @Column(name="transaction_type",nullable=false,length=20) private TransactionType transactionType; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="account_id") private Account account; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id") private User user; @Column(name="occurred_at",nullable=false) private Instant occurredAt; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt; protected FinanceTransaction(){} public FinanceTransaction(BigDecimal a,String c,String d,TransactionType t,Account ac,User u,Instant o){amount=a;category=c;description=d;transactionType=t;account=ac;user=u;occurredAt=o==null?Instant.now():o;} @PrePersist void c(){createdAt=Instant.now();} public Long getId(){return id;} public BigDecimal getAmount(){return amount;} public String getCategory(){return category;} public String getDescription(){return description;} public TransactionType getTransactionType(){return transactionType;} public Account getAccount(){return account;} public Instant getOccurredAt(){return occurredAt;} }
